class _UpdateRecordingPixmapItem(QGraphicsPixmapItem):
    """Pixmap item that records the repaint requests made on it."""

    def __init__(self, *args):
        super().__init__(*args)
        self.update_calls = 0

    def update(self, *args):
        self.update_calls += 1
        super().update(*args)


